#include <SPI.h>
#include <nRF24L01.h>
#include <RF24.h>

RF24 radio(7, 8); // CE, CSN
const byte address[6] = "00001";

struct PacketData {
  int joyX;
  int joyY;
  byte button;
};

void setup() {
  Serial.begin(9600);
  radio.begin();
  radio.openWritingPipe(address);
  radio.setPALevel(RF24_PA_LOW);
  radio.stopListening();
}

void loop() {
  PacketData data;
  data.joyX = analogRead(A0);
  data.joyY = analogRead(A1);
  data.button = digitalRead(2);

  radio.write(&data, sizeof(PacketData));
  delay(20);
}
